mapper.delete:
delete from FIN_CASH_CALC_RULE


	    AND EFF_DATE = TO_DATE(#{effDate},'YYYY-MM-DD')


		AND IS_INITIAL = #{isInitial}


		AND CALC_TYPE = #{calcType}

mapper.select:
        select
        	to_char(CDATE, 'yyyy-MM-dd') as HOLIDATE
        from
        	VAL_VW_MST_HOLIDAY
        where
        	IS_HOLIDAY > 0

		  		and CDATE >= #{startDate, jdbcType=DATE}


		  		and CDATE <= #{endDate, jdbcType=DATE}


		  		and TRADE_CALENDAR_ID = #{dealCalId}
